 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.website_domain := public.normalize_domain(new.website_url);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_hot_lead_outcome(p_hot_lead_id uuid, p_status text, p_note text DEFAULT NULL::text, p_call_outcome text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lead public.hot_leads;
begin
  select * into v_lead from public.hot_leads where id = p_hot_lead_id;
  if v_lead.id is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if not public.is_admin()
     and v_lead.client_id is distinct from public.current_client_id() then
    return jsonb_build_object('ok', false, 'error', 'not_permitted');
  end if;

  if p_status is not null and p_status not in ('new','viewed','contacted','won','lost') then
    return jsonb_build_object('ok', false, 'error', 'bad_status');
  end if;

  if p_call_outcome is not null
     and p_call_outcome not in ('rejected','call_later','meeting_agreed') then
    return jsonb_build_object('ok', false, 'error', 'bad_call_outcome');
  end if;

  update public.hot_leads
    set status = coalesce(p_status, status),
        outcome_note = coalesce(p_note, outcome_note)
    where id = p_hot_lead_id;

  if p_call_outcome is not null then
    update public.prospects
      set call_outcome = p_call_outcome, call_outcome_at = now(), updated_at = now()
      where id = v_lead.prospect_id;
  end if;

  -- Keep the prospect's own status in step with the lead's.
  if p_status in ('won', 'lost') then
    update public.prospects
      set pipeline_status = p_status, updated_at = now()
      where id = v_lead.prospect_id;
  elsif p_status = 'contacted' then
    update public.prospects
      set pipeline_status = 'called', updated_at = now()
      where id = v_lead.prospect_id
        and pipeline_status not in ('won', 'lost');
  end if;

  return jsonb_build_object('ok', true, 'hot_lead_id', p_hot_lead_id,
    'status', coalesce(p_status, v_lead.status));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_mailbox_auth(p_client_id uuid, p_result jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ok boolean;
begin
  update public.client_email_credentials
     set auth_check = p_result, auth_checked_at = now()
   where client_id = p_client_id and status = 'active';
  ok := coalesce((p_result->>'spf')::boolean, false)
        and coalesce((p_result->>'dkim')::boolean, false)
        and coalesce((p_result->>'dmarc')::boolean, false);
  if not ok and not exists (
    select 1 from public.mailbox_events
     where client_id = p_client_id and event_type = 'auth_warning' and created_at > now() - interval '7 days'
  ) then
    insert into public.mailbox_events (client_id, event_type, detail)
    values (p_client_id, 'auth_warning', p_result);
  end if;
end $function$
;

