 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_prospect_note(p_prospect_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid;
begin
  select client_id into v_client from public.prospects where id = p_prospect_id;
  if v_client is null then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;

  if not public.is_admin() and v_client is distinct from public.current_client_id() then
    return jsonb_build_object('ok', false, 'error', 'not_permitted');
  end if;

  if length(coalesce(p_note, '')) > 4000 then
    return jsonb_build_object('ok', false, 'error', 'note_too_long', 'max', 4000);
  end if;

  update public.prospects
    set client_note = nullif(btrim(coalesce(p_note, '')), ''), updated_at = now()
    where id = p_prospect_id;

  return jsonb_build_object('ok', true, 'prospect_id', p_prospect_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_sequence_paused(p_prospect_id uuid, p_paused boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_client uuid;
begin
  select client_id into v_client from public.prospects where id = p_prospect_id;
  if v_client is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.can_manage_client(v_client) then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  update public.prospects set sequence_paused = p_paused, updated_at = now() where id = p_prospect_id;
  return jsonb_build_object('ok', true, 'paused', p_paused);
