CREATE OR REPLACE FUNCTION public.sign_off_first_name(p_representative text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(split_part(btrim(coalesce(p_representative, '')), ' ', 1), '');
$function$
;

CREATE OR REPLACE FUNCTION public.sign_off_has_name(p_body text, p_representative text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare v_first text := public.sign_off_first_name(p_representative); v_pos int; v_main text; v_tail text;
begin
  if v_first is null or p_body is null then return true; end if;
  v_pos := public.email_footer_start(p_body);
  v_main := case when v_pos > 0 then left(p_body, v_pos - 1) else p_body end;
  select string_agg(l, E'\n' order by n) into v_tail from (
    select l, n from (
      select btrim(l) l, n from unnest(string_to_array(v_main, E'\n')) with ordinality as t(l, n)
    ) x where l <> '' order by n desc limit 4) y;
  return position(lower(v_first) in lower(coalesce(v_tail, ''))) > 0;
end; $function$
;

CREATE OR REPLACE FUNCTION public.simulate_sandbox_discovery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid; v_sandbox boolean; v_camp record;
  v_mailbox text; v_local text; v_domain text;
  v_queries text[]; v_locs text[];
  v_n int; v_run text; v_items jsonb := '[]'::jsonb; v_i int;
  v_q text; v_loc text; v_result jsonb;
  v_suffix text[] := array['Studio','Group','Partners','& Co','Works','Collective','Centre','Hub'];
begin
  select c.client_id, cl.is_sandbox into v_client, v_sandbox
    from campaigns c join clients cl on cl.id = c.client_id where c.id = new.campaign_id;
  if not coalesce(v_sandbox, false) then
    return new;  -- real clients: untouched, WF0b picks the row up as before
  end if;

  select lower(email_address) into v_mailbox from client_email_credentials
   where client_id = v_client and status = 'active' limit 1;
  if v_mailbox is null then
    raise exception 'Connect a Gmail account for this sandbox first: simulated prospects are addressed to it.'
      using errcode = 'check_violation';
  end if;
  v_local := split_part(v_mailbox, '@', 1);
  v_domain := split_part(v_mailbox, '@', 2);

  select * into v_camp from campaigns where id = new.campaign_id;
  v_queries := coalesce(nullif(array_remove(v_camp.search_queries, ''), '{}'), array['business']);
  v_locs := coalesce(nullif(array_remove(v_camp.target_locations, ''), '{}'), array['Testville']);
  v_n := greatest(1, least(coalesce(v_camp.max_results, 8), 8));
  -- A short per-launch tag keeps every relaunch's addresses unique (prospects are
  -- unique by email per client), while staying derived from the sandbox mailbox.
  v_run := substr(md5(new.campaign_id::text || clock_timestamp()::text), 1, 5);

  for v_i in 1..v_n loop
    v_q := v_queries[1 + ((v_i - 1) % array_length(v_queries, 1))];
    v_loc := v_locs[1 + ((v_i - 1) % array_length(v_locs, 1))];
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'title', initcap(v_q) || ' ' || v_suffix[1 + ((v_i - 1) % array_length(v_suffix, 1))] || ' ' || v_i,
      'email', v_local || '+sbx-d' || v_run || lpad(v_i::text, 2, '0') || '@' || v_domain,
      'phone', '+1 555 01' || lpad(v_i::text, 2, '0'),
      'categoryName', v_q,
      'city', v_loc,
      'sandbox_simulated', true));
  end loop;

  update campaigns set scrape_status = 'running', scrape_started_at = now(), scrape_error = null,
         scrape_failure_reason = null, scrape_finished_at = null,
         scrape_attempt_count = coalesce(scrape_attempt_count, 0) + 1
   where id = new.campaign_id;

  insert into raw_scrapes (campaign_id, apify_dataset_id, location, raw_data, import_status)
  values (new.campaign_id, 'sandbox-' || v_run, v_locs[1], v_items, 'pending');

  insert into scrape_import_jobs (campaign_id) values (new.campaign_id)
  returning result into v_result;

  update campaigns set last_scraped_at = now(), scrape_status = 'complete', scrape_error = null,
         scrape_failure_reason = null, scrape_finished_at = now(), last_scrape_summary = v_result
   where id = new.campaign_id;

  new.status := 'done';
  new.started_at := now();
  new.finished_at := now();
  new.result := coalesce(v_result, '{}'::jsonb) || jsonb_build_object('sandbox_simulated', true);
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.stamp_profile_activated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.last_sign_in_at is not null and (old.last_sign_in_at is distinct from new.last_sign_in_at) then
    update public.profiles set activated_at = new.last_sign_in_at
    where id = new.id and activated_at is null;
  end if;
  return new;
end; $function$
;

CREATE OR REPLACE FUNCTION public.stop_followups(p_prospect_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_client uuid; v_n int;
begin
  select client_id into v_client from public.prospects where id = p_prospect_id;
  if v_client is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.can_manage_client(v_client) then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  update public.prospects set followups_stopped = true, updated_at = now() where id = p_prospect_id;
  with u as (update public.messages set approval_status = 'rejected', reject_reason = 'followups_stopped', updated_at = now()
             where prospect_id = p_prospect_id and message_type <> 'initial'
               and send_status = 'not_sent' and approval_status <> 'rejected' returning 1)
  select count(*) into v_n from u;
  update public.follow_up_schedules set status = 'cancelled', updated_at = now()
    where prospect_id = p_prospect_id and status in ('pending','generating','generated')
      and not exists (select 1 from public.messages m where m.prospect_id = p_prospect_id and m.message_type <> 'initial' and m.send_status = 'sent' and m.sent_at >= follow_up_schedules.due_at - interval '1 day');
  return jsonb_build_object('ok', true, 'followups_cancelled', v_n);
end; $function$
;

CREATE OR REPLACE FUNCTION public.suggest_campaign_inputs(p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_icp public.client_icp;
  v_emailed integer := 0;
  v_positive integer := 0;
  v_terms jsonb := '[]'::jsonb;
  v_locs jsonb := '[]'::jsonb;
  v_confidence text;
  v_limits public.scrape_limits;
begin
  if not public.is_admin() and not public.is_trusted_backend()
     and p_client_id is distinct from public.current_client_id()
     and p_client_id is distinct from public.impersonating_client_id() then
    return jsonb_build_object('ok', false, 'error', 'not_permitted');
  end if;

  select * into v_icp from public.client_icp where client_id = p_client_id;
  select * into v_limits from public.scrape_limits where id = 1;

  select coalesce(sum(t.emailed), 0), coalesce(sum(t.positive), 0)
    into v_emailed, v_positive
  from public.client_targeting_performance(p_client_id) t;

  v_confidence := case
    when v_positive >= 10 then 'usable'
    when v_positive > 0 then 'thin'
    else 'none'
  end;

  -- Proven categories, with their numbers so the UI can show the evidence.
  select coalesce(jsonb_agg(jsonb_build_object(
           'term', t.category, 'source', 'results',
           'evidence', jsonb_build_object('emailed', t.emailed, 'replied', t.replied,
                                          'positive', t.positive))
         order by t.positive desc, t.emailed desc), '[]'::jsonb)
    into v_terms
  from public.client_targeting_performance(p_client_id) t
  where t.positive > 0 and t.category <> 'Uncategorised';

  -- Then the website-derived segments that are not already in the list above.
  v_terms := v_terms || (
    select coalesce(jsonb_agg(jsonb_build_object(
             'term', term, 'source', 'website', 'evidence', null)), '[]'::jsonb)
    from unnest(coalesce(v_icp.suggested_search_terms, '{}'::text[])) term
    where not exists (
      select 1 from jsonb_array_elements(v_terms) e where e->>'term' = term)
  );

  select coalesce(jsonb_agg(jsonb_build_object(
           'location', l.location, 'source', 'history',
           'evidence', jsonb_build_object('campaigns', l.campaigns))
         order by l.campaigns desc, l.location), '[]'::jsonb)
    into v_locs
  from public.client_suggested_locations(p_client_id) l;

  -- Nothing run yet: fall back to the ICP's locations.
  if jsonb_array_length(v_locs) = 0 then
    select coalesce(jsonb_agg(jsonb_build_object(
             'location', loc, 'source', 'profile', 'evidence', null)), '[]'::jsonb)
      into v_locs
    from unnest(coalesce(v_icp.target_locations, '{}'::text[])) loc;
  end if;

  return jsonb_build_object(
    'ok', true,
    'has_icp', v_icp.client_id is not null,
    'icp_derived_at', v_icp.derived_at,
    'confidence', v_confidence,
    'history', jsonb_build_object('emailed', v_emailed, 'positive', v_positive),
    'terms', v_terms,
    'locations', v_locs,
    'pain_points', coalesce(to_jsonb(v_icp.pain_points), '[]'::jsonb),
    'value_props', coalesce(to_jsonb(v_icp.value_props), '[]'::jsonb),
    -- So the UI can stop the client selecting a combination the launch
    -- validator would then reject.
    'limits', jsonb_build_object(
      'max_search_terms', v_limits.max_search_terms,
      'max_locations', v_limits.max_locations,
      'max_term_location_pairs', v_limits.max_term_location_pairs));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.suppress_prospects_for_email(p_email text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer := 0;
begin
  if p_email is null or btrim(p_email) = '' then return 0; end if;

  with flagged as (
    update public.prospects p
       set followups_stopped = true, updated_at = now()
     where lower(p.email) = lower(btrim(p_email)) and not p.followups_stopped
    returning 1
  )
  select count(*) into v_n from flagged;

  update public.messages m
     set approval_status = 'rejected', reject_reason = 'prospect_closed', updated_at = now()
   where m.prospect_id in (select id from public.prospects where lower(email) = lower(btrim(p_email)))
     and m.send_status = 'not_sent'
     and m.approval_status in ('pending', 'approved');

  update public.follow_up_schedules s
     set status = 'cancelled', updated_at = now()
   where s.prospect_id in (select id from public.prospects where lower(email) = lower(btrim(p_email)))
     and s.status in ('pending', 'generating');

  return v_n;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.sweep_hot_lead_nudges()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_policy public.hot_lead_policy;
  v_queued integer := 0;
  v_escalated integer := 0;
  v_hour integer := extract(hour from now())::integer;
  v_quiet boolean;
begin
  select * into v_policy from public.hot_lead_policy where id = 1;
  if v_policy.id is null then
    return jsonb_build_object('ok', false, 'error', 'no_policy');
  end if;

  -- Quiet hours. Handles the wrap over midnight (21:00 to 08:00).
  if v_policy.quiet_hours_start > v_policy.quiet_hours_end then
    v_quiet := v_hour >= v_policy.quiet_hours_start or v_hour < v_policy.quiet_hours_end;
  else
    v_quiet := v_hour >= v_policy.quiet_hours_start and v_hour < v_policy.quiet_hours_end;
  end if;

  if v_quiet then
    return jsonb_build_object('ok', true, 'skipped', 'quiet_hours', 'hour', v_hour);
  end if;

  -- Reminders to the client.
  with due as (
    select h.id, h.client_id, h.nudge_count, h.status,
           coalesce(p.business_name, 'A prospect') as business_name,
           h.routed_at
    from public.hot_leads h
    left join public.prospects p on p.id = h.prospect_id
    where h.status in ('new', 'viewed')
      and h.nudge_count < v_policy.max_nudges
      and (h.last_nudged_at is null
           or h.last_nudged_at < now() - make_interval(hours => v_policy.nudge_after_hours))
      and h.routed_at < now() - make_interval(
            hours => case when h.status = 'new'
                          then v_policy.nudge_after_hours
                          else v_policy.second_nudge_after_hours end)
  ),
  queued as (
    insert into public.notifications (client_id, hot_lead_id, channel, body, status,
                                      purpose, recipient)
    select d.client_id, d.id, 'whatsapp',
      'Shorty Harris: '
      || case when d.status = 'new' then 'You have not opened ' else 'Still waiting on ' end
      || case when length(d.business_name) > 40
              then left(d.business_name, 37) || '...' else d.business_name end
      || ' - hot since '
      || to_char(d.routed_at, 'DD Mon')
      || '. Leads go cold fast. https://shortyharris.com/app',
      'pending', 'hot_lead_nudge', 'client'
    from due d
    returning hot_lead_id
  )
  update public.hot_leads h
    set nudge_count = h.nudge_count + 1, last_nudged_at = now()
    where h.id in (select hot_lead_id from queued);

  get diagnostics v_queued = row_count;

  -- Escalation to the agency.
  with stale as (
    select h.id, h.client_id,
           coalesce(p.business_name, 'A prospect') as business_name,
           coalesce(c.business_name, 'A client') as client_name,
           h.routed_at, h.status
    from public.hot_leads h
    left join public.prospects p on p.id = h.prospect_id
    left join public.clients c on c.id = h.client_id
    where h.status in ('new', 'viewed')
      and h.escalated_at is null
      and h.routed_at < now() - make_interval(hours => v_policy.escalate_after_hours)
  ),
  queued_esc as (
    insert into public.notifications (client_id, hot_lead_id, channel, body, status,
                                      purpose, recipient)
    select s.client_id, s.id, 'sms',
      'Shorty Harris: ' || s.client_name || ' has not acted on the hot lead '
      || s.business_name || ' (hot since ' || to_char(s.routed_at, 'DD Mon')
      || ', status ' || s.status || '). A credit was charged for it.',
      'pending', 'hot_lead_escalation', 'agency'
    from stale s
    returning hot_lead_id
  )
  update public.hot_leads h
    set escalated_at = now()
    where h.id in (select hot_lead_id from queued_esc);

  get diagnostics v_escalated = row_count;

  return jsonb_build_object('ok', true, 'nudges_queued', v_queued,
    'escalations_queued', v_escalated, 'hour', v_hour);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.target_areas_valid(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  a jsonb;
begin
  if p is null then return true; end if;
  if jsonb_typeof(p) <> 'array' then return false; end if;
  if jsonb_array_length(p) > 25 then return false; end if;

  for a in select value from jsonb_array_elements(p) loop
    if jsonb_typeof(a) <> 'object' then return false; end if;
    if coalesce(a->>'mode', '') not in ('text', 'radius') then return false; end if;
    if coalesce(btrim(a->>'label'), '') = '' then return false; end if;

    if a->>'mode' = 'radius' then
      if (a->>'lat') is null or (a->>'lat') !~ '^-?[0-9.]+$' then return false; end if;
      if (a->>'lng') is null or (a->>'lng') !~ '^-?[0-9.]+$' then return false; end if;
      if (a->>'radius_km') is null or (a->>'radius_km') !~ '^[0-9.]+$' then return false; end if;
      if (a->>'lat')::numeric not between -90 and 90 then return false; end if;
      if (a->>'lng')::numeric not between -180 and 180 then return false; end if;
      -- 0.6 to 50 miles. 81 rather than 80 because the UI collects miles and
      -- 50 miles converts to 80.47 km, which a round 80 would reject. Beyond
      -- this the scraper subdivides into many searches and the run time stops
      -- being predictable.
      if (a->>'radius_km')::numeric not between 1 and 81 then return false; end if;
    end if;
  end loop;

  return true;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_suppress_new_prospect_on_dnc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.email is not null and exists (
       select 1 from public.do_not_contact d where lower(d.email) = lower(NEW.email)) then
    NEW.followups_stopped := true;
  end if;
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_suppress_prospects_on_dnc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.suppress_prospects_for_email(NEW.email);
  return NEW;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.unsubscribe_by_token(p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prospect record;
begin
  select id, email, business_name, client_id
    into v_prospect
  from public.prospects where unsubscribe_token = p_token;

  if v_prospect.id is null then
    -- Deliberately vague: a valid-looking response for an invalid token would
    -- let someone probe for live tokens.
    return jsonb_build_object('ok', false, 'reason', 'invalid_token');
  end if;

  if v_prospect.email is not null then
    insert into public.do_not_contact (email, reason, source_prospect_id)
    values (lower(v_prospect.email), 'opt_out', v_prospect.id)
    on conflict (lower(email)) where email is not null do nothing;
  end if;

  update public.prospects
    set pipeline_status = 'lost', updated_at = now()
    where id = v_prospect.id and pipeline_status not in ('won', 'lost');

  update public.follow_up_schedules
    set status = 'cancelled', updated_at = now()
    where prospect_id = v_prospect.id and status in ('pending', 'generating');

  update public.messages
    set send_status = 'blocked_dnc', updated_at = now()
    where prospect_id = v_prospect.id
      and send_status in ('not_sent', 'queued', 'scheduled');

  return jsonb_build_object('ok', true, 'business_name', v_prospect.business_name);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_campaign_inputs(p_search_queries text[], p_target_locations text[], p_max_results integer, p_for_launch boolean, p_target_areas jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limits public.scrape_limits;
  v_terms integer := coalesce(array_length(p_search_queries, 1), 0);
  v_locs integer;
  v_violations jsonb := '[]'::jsonb;
begin
  select * into v_limits from public.scrape_limits where id = 1;

  if p_target_areas is not null and jsonb_typeof(p_target_areas) = 'array' then
    v_locs := jsonb_array_length(p_target_areas);
  else
    v_locs := coalesce(array_length(p_target_locations, 1), 0);
  end if;

  if v_limits is null then
    return jsonb_build_object('valid', true, 'violations', v_violations);
  end if;

  if not public.target_areas_valid(p_target_areas) then
    v_violations := v_violations || jsonb_build_object(
      'field', 'target_areas', 'code', 'invalid_target_areas', 'limit', 25, 'actual', 0);
  end if;

  if v_terms > v_limits.max_search_terms then
    v_violations := v_violations || jsonb_build_object(
      'field', 'search_queries', 'code', 'too_many_search_terms',
      'limit', v_limits.max_search_terms, 'actual', v_terms);
  end if;

  if v_locs > v_limits.max_locations then
    v_violations := v_violations || jsonb_build_object(
      'field', 'target_locations', 'code', 'too_many_locations',
      'limit', v_limits.max_locations, 'actual', v_locs);
  end if;

  if v_terms * v_locs > v_limits.max_term_location_pairs then
    v_violations := v_violations || jsonb_build_object(
      'field', 'search_queries', 'code', 'too_many_term_location_pairs',
      'limit', v_limits.max_term_location_pairs, 'actual', v_terms * v_locs);
  end if;

  if coalesce(p_max_results, 0) > v_limits.max_results then
    v_violations := v_violations || jsonb_build_object(
      'field', 'max_results', 'code', 'max_results_too_high',
      'limit', v_limits.max_results, 'actual', p_max_results);
  end if;

  if p_for_launch then
    if v_terms = 0 then
      v_violations := v_violations || jsonb_build_object(
        'field', 'search_queries', 'code', 'no_search_terms', 'limit', 1, 'actual', 0);
    end if;
    if v_locs = 0 then
      v_violations := v_violations || jsonb_build_object(
        'field', 'target_locations', 'code', 'no_locations', 'limit', 1, 'actual', 0);
    end if;
  end if;

  return jsonb_build_object(
    'valid', jsonb_array_length(v_violations) = 0,
    'violations', v_violations,
    'limits', to_jsonb(v_limits));
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_campaign_inputs(p_search_queries text[], p_target_locations text[], p_max_results integer, p_for_launch boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limits public.scrape_limits;
  v_terms integer := coalesce(array_length(p_search_queries, 1), 0);
  v_locs integer := coalesce(array_length(p_target_locations, 1), 0);
  v_violations jsonb := '[]'::jsonb;
begin
  select * into v_limits from public.scrape_limits where id = 1;

  if v_limits is null then
    return jsonb_build_object('valid', true, 'violations', v_violations);
  end if;

  if v_terms > v_limits.max_search_terms then
    v_violations := v_violations || jsonb_build_object(
      'field', 'search_queries',
      'code', 'too_many_search_terms',
      'limit', v_limits.max_search_terms,
      'actual', v_terms
    );
  end if;

  if v_locs > v_limits.max_locations then
    v_violations := v_violations || jsonb_build_object(
      'field', 'target_locations',
      'code', 'too_many_locations',
      'limit', v_limits.max_locations,
      'actual', v_locs
    );
  end if;

  if v_terms * v_locs > v_limits.max_term_location_pairs then
    v_violations := v_violations || jsonb_build_object(
      'field', 'search_queries',
      'code', 'too_many_term_location_pairs',
      'limit', v_limits.max_term_location_pairs,
      'actual', v_terms * v_locs
    );
  end if;

  if coalesce(p_max_results, 0) > v_limits.max_results then
    v_violations := v_violations || jsonb_build_object(
      'field', 'max_results',
      'code', 'max_results_too_high',
      'limit', v_limits.max_results,
      'actual', p_max_results
    );
  end if;

  -- Empty inputs are fine while drafting but cannot be launched: WF0 would scrape
  -- nothing and report success, which is exactly the silent-failure shape here.
  if p_for_launch then
    if v_terms = 0 then
      v_violations := v_violations || jsonb_build_object(
        'field', 'search_queries', 'code', 'no_search_terms', 'limit', 1, 'actual', 0
      );
    end if;
    if v_locs = 0 then
      v_violations := v_violations || jsonb_build_object(
        'field', 'target_locations', 'code', 'no_locations', 'limit', 1, 'actual', 0
      );
    end if;
  end if;

  return jsonb_build_object(
    'valid', jsonb_array_length(v_violations) = 0,
    'violations', v_violations,
    'limits', to_jsonb(v_limits)
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.validate_send_timezone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if not exists (select 1 from pg_catalog.pg_timezone_names where name = new.send_timezone) then
    raise exception 'Invalid send_timezone: %', new.send_timezone;
  end if;
  return new;
end $function$
;

create or replace view public.admin_notification_recipients with (security_invoker=true) as
 SELECT p.id,
    p.full_name,
    u.email
   FROM (public.profiles p
     JOIN auth.users u ON ((u.id = p.id)))
  WHERE (p.role = 'admin'::text);

create or replace view public.ai_sweep_gate as
 SELECT 1 AS gate_open
   FROM public.ai_breaker
  WHERE ((id = 1) AND (state = 'closed'::text));

create or replace view public.approval_reminders_due as
 WITH local_now AS (
         SELECT (now() AT TIME ZONE 'America/Denver'::text) AS t
        ), pending AS (
         SELECT m.client_id,
            (count(DISTINCT m.prospect_id))::integer AS prospects,
            min(m.created_at) AS oldest
           FROM (public.messages m
             JOIN public.prospects p ON ((p.id = m.prospect_id)))
          WHERE ((m.approval_status = 'pending'::text) AND (m.send_status = 'not_sent'::text) AND (COALESCE(p.is_sandbox, false) = false) AND (p.pipeline_status <> ALL (ARRAY['bounced'::text, 'lost'::text, 'replied'::text, 'hot_lead'::text, 'won'::text, 'called'::text])) AND (NOT (EXISTS ( SELECT 1
                   FROM public.do_not_contact d
                  WHERE (lower(d.email) = lower(p.email))))) AND (NOT public.is_send_rule_held(p.email, m.campaign_id, m.client_id)))
          GROUP BY m.client_id
        )
 SELECT c.id AS client_id,
    c.business_name,
    c.contact_name,
    btrim(c.contact_email) AS contact_email,
    pe.prospects AS pending_prospects,
    (GREATEST((0)::numeric, floor((EXTRACT(epoch FROM (now() - pe.oldest)) / (86400)::numeric))))::integer AS days_waiting,
    (NOT (EXISTS ( SELECT 1
           FROM public.approval_reminder_log l
          WHERE ((l.client_id = c.id) AND (l.status = 'sent'::text))))) AS is_first,
    (ln.t)::date AS reminder_date
   FROM ((pending pe
     JOIN public.clients c ON ((c.id = pe.client_id)))
     CROSS JOIN local_now ln)
  WHERE ((c.contact_email IS NOT NULL) AND (btrim(c.contact_email) <> ''::text) AND (COALESCE(c.status, 'active'::text) = 'active'::text) AND (EXTRACT(isodow FROM ln.t) >= (1)::numeric) AND (EXTRACT(isodow FROM ln.t) <= (5)::numeric) AND (EXTRACT(hour FROM ln.t) >= (8)::numeric) AND (EXTRACT(hour FROM ln.t) <= (16)::numeric) AND (NOT (EXISTS ( SELECT 1
           FROM public.approval_reminder_log l
          WHERE ((l.client_id = c.id) AND (l.reminder_date = (ln.t)::date) AND (l.status = ANY (ARRAY['pending'::text, 'sent'::text])))))));

create or replace view public.client_send_limits with (security_invoker=true) as
 SELECT id,
    send_timezone,
    public.mailbox_daily_cap(id) AS daily_cap,
        CASE
            WHEN (is_sandbox AND (NOT sandbox_warmup)) THEN 'warm'::text
            ELSE COALESCE(( SELECT c.warmup_mode
               FROM public.client_email_credentials c
              WHERE ((c.client_id = cl.id) AND (c.status = 'active'::text))
              ORDER BY c.created_at
             LIMIT 1), 'warm'::text)
        END AS warmup_mode,
    is_sandbox,
        CASE
            WHEN is_sandbox THEN sandbox_minutes_advanced
            ELSE 0
        END AS clock_offset_minutes,
    (is_sandbox AND (NOT sandbox_warmup)) AS sandbox_fast
   FROM public.clients cl;

create or replace view public.client_usage with (security_invoker=true) as
 SELECT c.id AS client_id,
    c.business_name,
    c.monthly_prospect_limit,
    c.max_campaigns,
    COALESCE(p.used_this_month, (0)::bigint) AS prospects_this_month,
    GREATEST((c.monthly_prospect_limit - COALESCE(p.used_this_month, (0)::bigint)), (0)::bigint) AS prospects_remaining,
    COALESCE(cm.campaign_count, (0)::bigint) AS campaign_count,
    GREATEST((c.max_campaigns - COALESCE(cm.campaign_count, (0)::bigint)), (0)::bigint) AS campaigns_remaining,
    (date_trunc('month'::text, now()) + '1 mon'::interval) AS limit_resets_at
   FROM ((public.clients c
     LEFT JOIN ( SELECT prospects.client_id,
            count(*) AS used_this_month
           FROM public.prospects
          WHERE (prospects.created_at >= date_trunc('month'::text, now()))
          GROUP BY prospects.client_id) p ON ((p.client_id = c.id)))
     LEFT JOIN ( SELECT campaigns.client_id,
            count(*) AS campaign_count
           FROM public.campaigns
          GROUP BY campaigns.client_id) cm ON ((cm.client_id = c.id)));

create or replace view public.duplicate_send_alerts with (security_invoker=true) as
 SELECT 'same_step_sent_twice'::text AS alert_type,
    m.client_id,
    m.prospect_id,
    m.message_type AS detail,
    (count(*))::integer AS occurrences,
    min(m.sent_at) AS first_at,
    max(m.sent_at) AS last_at
   FROM public.messages m
  WHERE ((m.send_status = 'sent'::text) AND (m.sent_at > (now() - '30 days'::interval)))
  GROUP BY m.client_id, m.prospect_id, m.message_type
 HAVING (count(*) > 1)
UNION ALL
 SELECT 'multiple_sends_within_24h'::text AS alert_type,
    m.client_id,
    m.prospect_id,
    'mixed'::text AS detail,
    (count(*))::integer AS occurrences,
    min(m.sent_at) AS first_at,
    max(m.sent_at) AS last_at
   FROM public.messages m
  WHERE ((m.send_status = 'sent'::text) AND (m.sent_at > (now() - '30 days'::interval)))
  GROUP BY m.client_id, m.prospect_id, (date_trunc('day'::text, m.sent_at))
 HAVING (count(*) > 1)
UNION ALL
 SELECT 'claimed_but_unconfirmed'::text AS alert_type,
    m.client_id,
    m.prospect_id,
    m.message_type AS detail,
    1 AS occurrences,
    m.send_claimed_at AS first_at,
    m.send_claimed_at AS last_at
   FROM public.messages m
  WHERE ((m.send_claimed_at IS NOT NULL) AND (m.send_status <> 'sent'::text) AND (m.send_status <> ALL (ARRAY['failed'::text, 'blocked_dnc'::text])) AND (m.send_claimed_at < (now() - '00:30:00'::interval)) AND (m.send_claimed_at > (now() - '30 days'::interval)));

create or replace view public.mailbox_auth_targets with (security_invoker=true) as
 SELECT client_id,
    email_address,
    lower(split_part(email_address, '@'::text, 2)) AS domain
   FROM public.client_email_credentials cec
  WHERE ((status = 'active'::text) AND (lower(split_part(email_address, '@'::text, 2)) <> ALL (ARRAY['gmail.com'::text, 'googlemail.com'::text])));

create or replace view public.mailbox_events_pending with (security_invoker=true) as
 SELECT e.id,
    e.client_id,
    c.business_name,
    e.event_type,
    e.detail,
    e.created_at
   FROM (public.mailbox_events e
     JOIN public.clients c ON ((c.id = e.client_id)))
  WHERE (e.alerted_at IS NULL);

create or replace view public.messages_with_sender as
 SELECT m.id,
    m.prospect_id,
    m.campaign_id,
    m.client_id,
    m.channel,
    m.subject,
    m.body,
    m.message_type,
    m.approval_status,
    m.approved_by,
    m.approved_at,
    m.send_status,
    m.scheduled_for,
    m.sent_at,
    m.gmail_message_id,
    m.gmail_thread_id,
    m.created_at,
    m.updated_at,
    m.opened_at,
    m.open_count,
    cec.email_address AS sender_email,
    cec.status AS sender_status,
    c.business_name AS client_name,
    m.pending_since,
    m.angle,
    m.observation,
    m.observation_source_url
   FROM ((public.messages m
     LEFT JOIN public.client_email_credentials cec ON ((cec.client_id = m.client_id)))
     LEFT JOIN public.clients c ON ((c.id = m.client_id)));

create or replace view public.optout_list with (security_invoker=true) as
 SELECT d.id,
    d.email,
    d.reason,
    d.created_at,
    p.business_name,
    p.client_id,
    p.campaign_id,
    c.business_name AS client_name,
    camp.name AS campaign_name
   FROM (((public.do_not_contact d
     LEFT JOIN public.prospects p ON ((p.id = d.source_prospect_id)))
     LEFT JOIN public.clients c ON ((c.id = p.client_id)))
     LEFT JOIN public.campaigns camp ON ((camp.id = p.campaign_id)))
  ORDER BY d.created_at DESC;

create or replace view public.optout_stats with (security_invoker=true) as
 WITH real_dnc AS (
         SELECT d.reason,
            d.created_at
           FROM ((public.do_not_contact d
             LEFT JOIN public.prospects p ON ((p.id = d.source_prospect_id)))
             LEFT JOIN public.clients c ON ((c.id = p.client_id)))
          WHERE (NOT COALESCE(c.is_sandbox, false))
        ), real_replies AS (
         SELECT r.intent
           FROM (public.replies r
             LEFT JOIN public.clients c ON ((c.id = r.client_id)))
          WHERE (NOT COALESCE(c.is_sandbox, false))
        ), totals AS (
         SELECT ( SELECT count(*) AS count
                   FROM real_dnc
                  WHERE (real_dnc.reason IS DISTINCT FROM 'bounce'::text)) AS total_optouts,
            ( SELECT count(*) AS count
                   FROM real_replies
                  WHERE (real_replies.intent = 'stop'::text)) AS stop_replies,
            ( SELECT count(*) AS count
                   FROM real_replies
                  WHERE (real_replies.intent = 'not_interested'::text)) AS not_interested_replies,
            ( SELECT count(*) AS count
                   FROM real_dnc
                  WHERE ((real_dnc.reason IS DISTINCT FROM 'bounce'::text) AND (real_dnc.created_at >= (now() - '7 days'::interval)))) AS optouts_last_7_days,
            ( SELECT count(*) AS count
                   FROM real_dnc
                  WHERE ((real_dnc.reason IS DISTINCT FROM 'bounce'::text) AND (real_dnc.created_at >= (now() - '30 days'::interval)))) AS optouts_last_30_days
        )
 SELECT total_optouts,
    stop_replies,
    not_interested_replies,
    optouts_last_7_days,
    optouts_last_30_days
   FROM totals;

create or replace view public.replies_match_review as
 SELECT r.id AS reply_id,
    c.business_name AS client,
    p.business_name AS prospect,
    p.email AS prospect_email,
    r.intent,
    r.match_method,
    r.received_at,
    "left"(r.body, 240) AS excerpt,
    (EXISTS ( SELECT 1
           FROM public.hot_leads h
          WHERE (h.prospect_id = p.id))) AS has_hot_lead
   FROM ((public.replies r
     JOIN public.prospects p ON ((p.id = r.prospect_id)))
     JOIN public.clients c ON ((c.id = r.client_id)))
  WHERE ((r.match_method = 'domain'::text) AND (r.intent <> ALL (ARRAY['auto_reply'::text, 'bounced'::text, 'automated'::text, 'out_of_office'::text])))
  ORDER BY r.received_at DESC;

create or replace view public.sendable_messages as
 SELECT m.id,
    m.prospect_id,
    m.campaign_id,
    m.client_id,
    m.channel,
    m.subject,
    m.body,
    m.message_type,
    m.approval_status,
    m.approved_by,
    m.approved_at,
    m.send_status,
    m.scheduled_for,
    m.sent_at,
    m.gmail_message_id,
    m.gmail_thread_id,
    m.created_at,
    m.updated_at,
    m.opened_at,
    m.open_count,
    m.last_opened_at,
    m.send_claimed_at
   FROM (((public.messages m
     JOIN public.prospects p ON ((p.id = m.prospect_id)))
     LEFT JOIN public.campaigns c ON ((c.id = m.campaign_id)))
     LEFT JOIN public.clients cl ON ((cl.id = m.client_id)))
  WHERE ((m.approval_status = 'approved'::text) AND (m.send_status = 'not_sent'::text) AND COALESCE(( SELECT ps.unsubscribe_ok
           FROM public.platform_settings ps
          WHERE (ps.id = 1)), true) AND (COALESCE(cl.status, 'active'::text) = 'active'::text) AND public.sandbox_address_allowed(m.client_id, p.email) AND (p.pipeline_status <> ALL (ARRAY['replied'::text, 'hot_lead'::text, 'won'::text, 'lost'::text, 'called'::text, 'bounced'::text])) AND (p.sequence_paused = false) AND ((m.message_type = 'initial'::text) OR (p.followups_stopped = false)) AND (COALESCE(c.status, 'active'::text) <> ALL (ARRAY['paused'::text, 'cancelled'::text, 'draft'::text])) AND (NOT (EXISTS ( SELECT 1
           FROM public.do_not_contact d
          WHERE (lower(d.email) = lower(p.email))))) AND (NOT (((COALESCE(c.language, ''::text) = 'Czech'::text) OR public.is_eu_country(COALESCE(c.country, cl.country))) AND ((public.is_generic_mailbox(p.email) AND (NOT COALESCE(cl.allow_generic_mailboxes, false))) OR public.is_freemail(p.email)))) AND (NOT (EXISTS ( SELECT 1
           FROM public.country_send_holds h
          WHERE ((h.cleared = false) AND (h.country = upper(COALESCE(c.country, cl.country, ''::text))))))) AND ((m.message_type = 'initial'::text) OR (EXISTS ( SELECT 1
           FROM public.messages prev
          WHERE ((prev.prospect_id = m.prospect_id) AND (prev.send_status = 'sent'::text) AND (prev.message_type =
                CASE m.message_type
                    WHEN 'follow_up_d3'::text THEN 'initial'::text
                    WHEN 'follow_up_d7'::text THEN 'follow_up_d3'::text
                    WHEN 'follow_up_d14'::text THEN 'follow_up_d7'::text
                    ELSE NULL::text
                END) AND (public.add_business_days(prev.sent_at,
                CASE m.message_type
                    WHEN 'follow_up_d3'::text THEN 3
                    WHEN 'follow_up_d7'::text THEN 5
                    ELSE 7
                END, COALESCE(cl.send_timezone, 'America/Chicago'::text), upper(COALESCE(NULLIF(c.country, ''::text), NULLIF(cl.country, ''::text), 'US'::text))) <= now()))))) AND public.client_mailbox_ready(m.client_id) AND ((m.send_retry_at IS NULL) OR (m.send_retry_at <= now())));

create or replace view public.message_block_reasons as
 SELECT m.id AS message_id,
    m.client_id,
    m.prospect_id,
    m.campaign_id,
        CASE
            WHEN (NOT COALESCE(( SELECT ps.unsubscribe_ok
               FROM public.platform_settings ps
              WHERE (ps.id = 1)), true)) THEN 'unsubscribe_unhealthy'::text
            WHEN (p.pipeline_status = ANY (ARRAY['replied'::text, 'hot_lead'::text, 'won'::text, 'lost'::text, 'called'::text, 'bounced'::text])) THEN 'prospect_status'::text
            WHEN p.sequence_paused THEN 'sequence_paused'::text
            WHEN ((m.message_type <> 'initial'::text) AND p.followups_stopped) THEN 'followups_stopped'::text
            WHEN (COALESCE(c.status, 'active'::text) = ANY (ARRAY['paused'::text, 'cancelled'::text, 'draft'::text])) THEN 'campaign_inactive'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.do_not_contact d
              WHERE (lower(d.email) = lower(p.email)))) THEN 'do_not_contact'::text
            WHEN (((COALESCE(c.language, ''::text) = 'Czech'::text) OR public.is_eu_country(COALESCE(c.country, cl.country))) AND public.is_freemail(p.email)) THEN 'freemail_address'::text
            WHEN (((COALESCE(c.language, ''::text) = 'Czech'::text) OR public.is_eu_country(COALESCE(c.country, cl.country))) AND public.is_generic_mailbox(p.email) AND (NOT COALESCE(cl.allow_generic_mailboxes, false))) THEN 'generic_mailbox'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.country_send_holds h
              WHERE ((h.cleared = false) AND (h.country = upper(COALESCE(c.country, cl.country, ''::text)))))) THEN 'country_hold'::text
            WHEN (NOT public.client_mailbox_ready(m.client_id)) THEN 'no_gmail'::text
            WHEN (m.send_retry_at > now()) THEN 'retrying_send'::text
            ELSE 'waiting_followup_timing'::text
        END AS reason
   FROM (((public.messages m
     JOIN public.prospects p ON ((p.id = m.prospect_id)))
     LEFT JOIN public.campaigns c ON ((c.id = m.campaign_id)))
     LEFT JOIN public.clients cl ON ((cl.id = m.client_id)))
  WHERE ((m.approval_status = 'approved'::text) AND (m.send_status = 'not_sent'::text) AND (NOT (EXISTS ( SELECT 1
           FROM public.sendable_messages s
          WHERE (s.id = m.id)))) AND public.can_manage_client(m.client_id));

create or replace view public.sequence_writer_queue as
 SELECT p.id AS prospect_id,
    p.client_id,
    p.campaign_id,
    p.business_name,
    p.category,
    p.contact_name,
    p.unsubscribe_token,
    s.step AS message_type,
    s.day_label
   FROM ((public.prospects p
     JOIN public.campaigns c ON (((c.id = p.campaign_id) AND (c.upfront_sequence = true) AND (c.status = 'active'::text))))
     CROSS JOIN ( VALUES ('follow_up_d3'::text,3), ('follow_up_d7'::text,7), ('follow_up_d14'::text,14)) s(step, day_label))
  WHERE ((COALESCE(p.is_sandbox, false) = false) AND (COALESCE(p.sequence_paused, false) = false) AND (COALESCE(p.followups_stopped, false) = false) AND (p.pipeline_status <> ALL (ARRAY['replied'::text, 'hot_lead'::text, 'won'::text, 'lost'::text, 'called'::text, 'bounced'::text, 'generation_failed'::text, 'new'::text, 'generating'::text])) AND (EXISTS ( SELECT 1
           FROM public.messages i
          WHERE ((i.prospect_id = p.id) AND (i.message_type = 'initial'::text) AND (i.approval_status <> 'rejected'::text) AND (i.send_status <> 'failed'::text)))) AND (NOT (EXISTS ( SELECT 1
           FROM public.messages f
          WHERE ((f.prospect_id = p.id) AND (f.message_type = s.step) AND (f.approval_status <> 'rejected'::text) AND (f.send_status <> 'failed'::text))))) AND (NOT (EXISTS ( SELECT 1
           FROM public.do_not_contact d
          WHERE (lower(d.email) = lower(p.email))))));

create or replace view public.warm_prospects with (security_invoker=true) as
 SELECT p.id AS prospect_id,
    p.client_id,
    p.campaign_id,
    p.business_name,
    p.phone,
    p.email,
    p.category,
    p.location,
    COALESCE(sum(m.open_count), (0)::bigint) AS total_opens,
    max(m.opened_at) AS last_opened_at,
    min(m.sent_at) AS first_sent_at
   FROM (public.prospects p
     JOIN public.messages m ON (((m.prospect_id = p.id) AND (m.send_status = 'sent'::text))))
  WHERE (p.pipeline_status = 'contacted'::text)
  GROUP BY p.id
 HAVING (COALESCE(sum(m.open_count), (0)::bigint) >= 2)
  ORDER BY COALESCE(sum(m.open_count), (0)::bigint) DESC;

create or replace view public.weekly_client_summary as
 WITH w AS (
         SELECT (now() - '7 days'::interval) AS since,
            now() AS until,
            (now() - '14 days'::interval) AS prev_since
        ), human_intents AS (
         SELECT unnest(ARRAY['automated'::text, 'auto_reply'::text, 'out_of_office'::text, 'bounced'::text]) AS intent
        )
 SELECT id AS client_id,
    business_name,
    COALESCE(NULLIF(TRIM(BOTH FROM contact_name), ''::text), business_name) AS greeting_name,
    contact_email,
    COALESCE(NULLIF(send_timezone, ''::text), 'America/Chicago'::text) AS send_timezone,
    ( SELECT w.since
           FROM w) AS period_start,
    ( SELECT w.until
           FROM w) AS period_end,
    ( SELECT count(*) AS count
           FROM public.messages m
          WHERE ((m.client_id = c.id) AND (m.send_status = 'sent'::text) AND (m.sent_at >= ( SELECT w.since
                   FROM w)))) AS emails_sent,
    ( SELECT count(DISTINCT m.prospect_id) AS count
           FROM public.messages m
          WHERE ((m.client_id = c.id) AND (m.send_status = 'sent'::text) AND (m.sent_at >= ( SELECT w.since
                   FROM w)))) AS prospects_contacted,
    ( SELECT count(*) AS count
           FROM public.messages m
          WHERE ((m.client_id = c.id) AND (m.opened_at >= ( SELECT w.since
                   FROM w)))) AS emails_opened,
    ( SELECT count(*) AS count
           FROM public.replies r
          WHERE ((r.client_id = c.id) AND (r.received_at >= ( SELECT w.since
                   FROM w)) AND (r.intent IS NOT NULL) AND (NOT (r.intent IN ( SELECT human_intents.intent
                   FROM human_intents))))) AS replies,
    ( SELECT count(*) AS count
           FROM public.replies r
          WHERE ((r.client_id = c.id) AND (r.received_at >= ( SELECT w.since
                   FROM w)) AND (r.intent = 'interested'::text))) AS positive_replies,
    ( SELECT count(*) AS count
           FROM (public.do_not_contact d
             JOIN public.prospects p ON ((p.id = d.source_prospect_id)))
          WHERE ((p.client_id = c.id) AND (d.reason = ANY (ARRAY['opt_out'::text, 'stop_request'::text])) AND (d.created_at >= ( SELECT w.since
                   FROM w)))) AS unsubscribes,
    ( SELECT count(DISTINCT m.prospect_id) AS count
           FROM (public.messages m
             JOIN public.prospects p ON ((p.id = m.prospect_id)))
          WHERE ((m.client_id = c.id) AND (m.approval_status = 'pending'::text) AND (m.send_status = 'not_sent'::text) AND (p.pipeline_status <> ALL (ARRAY['replied'::text, 'hot_lead'::text, 'won'::text, 'lost'::text, 'called'::text, 'bounced'::text])))) AS prospects_awaiting_approval,
    ( SELECT count(*) AS count
           FROM public.campaigns k
          WHERE ((k.client_id = c.id) AND (k.status = 'active'::text))) AS active_campaigns,
    ( SELECT count(*) AS count
           FROM public.campaigns k
          WHERE ((k.client_id = c.id) AND ((k.status = 'paused'::text) OR (k.scrape_status = ANY (ARRAY['error'::text, 'failed'::text]))))) AS campaigns_needing_attention,
    ( SELECT count(*) AS count
           FROM public.messages m
          WHERE ((m.client_id = c.id) AND (m.send_status = 'sent'::text) AND (m.sent_at >= ( SELECT w.prev_since
                   FROM w)) AND (m.sent_at < ( SELECT w.since
                   FROM w)))) AS prev_emails_sent,
    ( SELECT count(*) AS count
           FROM public.replies r
          WHERE ((r.client_id = c.id) AND (r.received_at >= ( SELECT w.prev_since
                   FROM w)) AND (r.received_at < ( SELECT w.since
                   FROM w)) AND (r.intent IS NOT NULL) AND (NOT (r.intent IN ( SELECT human_intents.intent
                   FROM human_intents))))) AS prev_replies
   FROM public.clients c
  WHERE (status = 'active'::text);

