CREATE INDEX messages_client_rejected_at_idx ON public.messages USING btree (client_id, rejected_at) WHERE (approval_status = 'rejected'::text);

CREATE UNIQUE INDEX messages_one_followup_per_step ON public.messages USING btree (prospect_id, message_type) WHERE ((message_type <> 'initial'::text) AND (send_status <> 'failed'::text) AND (approval_status <> 'rejected'::text) AND (created_at >= '2026-10-09 00:00:00+00'::timestamp with time zone));

CREATE UNIQUE INDEX messages_prospect_type_active_uniq ON public.messages USING btree (prospect_id, message_type) WHERE ((approval_status <> 'rejected'::text) AND (send_status <> 'sent'::text));

CREATE UNIQUE INDEX payments_checkout_session_uniq ON public.payments USING btree (stripe_checkout_session_id) WHERE (stripe_checkout_session_id IS NOT NULL);

CREATE UNIQUE INDEX prospects_client_email_unique ON public.prospects USING btree (client_id, lower(TRIM(BOTH FROM email))) WHERE ((email IS NOT NULL) AND (email <> ''::text));

CREATE UNIQUE INDEX uniq_active_followup_per_prospect_day ON public.follow_up_schedules USING btree (prospect_id, follow_up_day) WHERE (status = ANY (ARRAY['pending'::text, 'generating'::text]));

CREATE UNIQUE INDEX uniq_pending_initial_msg_per_prospect ON public.messages USING btree (prospect_id) WHERE ((message_type = 'initial'::text) AND (approval_status = 'pending'::text) AND (send_status = 'not_sent'::text));

CREATE UNIQUE INDEX uniq_reply_gmail_message_id ON public.replies USING btree (gmail_message_id) WHERE ((gmail_message_id IS NOT NULL) AND (gmail_message_id <> ''::text));

