-- ==============================================================================================
-- Comments (37)
-- ==============================================================================================

comment on function public.approvals_schedule(p_client_id uuid) is 'Per-message estimated send time for the Approvals page. is_confirmed is true only when the time follows from real data (a follow-up whose previous email was actually sent, or a first touch in the very next send slot). Follow-up dates ignore the daily cap, so they are earliest eligible times, not guarantees. Overdue = estimated_send_at < now().';

comment on function public.bump_research_attempt(p_prospect_id uuid) is 'Counts research attempts so the retry sweep gives up after a few tries instead of re-running a hopeless prospect forever.';

comment on column public.campaigns.last_scrape_summary is 'Breakdown of the most recent scrape: total_scraped, total_with_email, skipped_dnc, skipped_duplicate, new_prospects. Lets the frontend distinguish "found nothing new because everything was already a prospect" from "found nothing" from a real failure.';

comment on column public.campaigns.scrape_attempt_count is 'Number of times a scrape has been started for this campaign. Lets the UI flag repeatedly failing campaigns.';

comment on column public.campaigns.scrape_enabled is 'WF0 only scrapes campaigns where this is true and status = active.';

comment on column public.campaigns.scrape_error is 'error message if scrape_status = failed';

comment on column public.campaigns.scrape_failure_reason is 'Machine-readable failure code when scrape_status = failed. Frontend maps it to a message plus a suggested fix. Null whenever scrape_status is not failed.';

comment on column public.campaigns.scrape_finished_at is 'When the last scrape reached a terminal state (complete or failed). Paired with scrape_started_at this gives real run durations.';

comment on column public.campaigns.scrape_started_at is 'timestamp when the current/last scrape was kicked off; used by frontend to detect stale/stuck runs';

comment on column public.campaigns.scrape_status is 'idle = never scraped or not currently running, running = WF0 in progress, complete = last scrape finished successfully, failed = last scrape errored';

comment on column public.campaigns.search_queries is 'Apify search terms, e.g. {hotels,lodges}. Combined with target_locations.';

comment on column public.campaigns.target_areas is 'Per-area targeting, authoritative when present; falls back to target_locations when null. Array of {mode:"text"|"radius", label, lat, lng, radius_km}. radius_km is kilometres because that is what the scraper accepts; the UI collects miles and converts.';

comment on column public.campaigns.target_locations is 'Locations to scrape, e.g. {Lusaka,Kafue}.';

comment on table public.client_email_credentials is 'Stores OAuth refresh tokens (or app passwords) for per-client Gmail sending. One credential per client.';

comment on table public.client_icp is 'Per-client ideal customer profile: who to target, used to pre-fill campaign search terms and locations. Derived from client_website_enrichment and campaign history, then editable by the client. edited_fields protects hand edits from being overwritten by re-derivation.';

comment on view public.client_usage is 'Current calendar-month prospect usage and campaign counts per client. Read by WF0 before scraping and by the admin client page.';

comment on column public.client_website_enrichment.website_domain is 'Normalised domain of website_url, maintained by trigger. Used to match a parked enrichment (client_id null) to a client once that client is created.';

comment on column public.clients.is_sandbox is 'Test account. Prospect addresses must derive from its own connected mailbox, Twilio is held, discovery is refused, and it is excluded from health monitors.';

comment on column public.clients.postal_address is 'Valid physical postal address for the CAN-SPAM footer. A street address, a registered PO box, or a registered commercial mailbox all qualify. Null falls back to the agency address when that is enabled, otherwise sending is blocked.';

comment on column public.clients.privacy_url is 'Optional link to the sender privacy notice. When set, it is added as a line in the email footer.';

comment on column public.clients.representative_name is 'Name of the person emails are signed off from, e.g. "Eugene Wilson". If null, emails sign off with the business name only.';

comment on column public.hot_leads.nudge_count is 'How many reminders have been sent to the client about this lead. Capped by hot_lead_policy.max_nudges so a quiet client is never spammed.';

comment on column public.messages.angle is 'Which researched angle this email used: SOCIAL, GEO or REDDIT. Null means the generic fallback was used.';

comment on column public.messages.observation is 'The verified observation about the prospect that this email opens with. Shown next to the draft on the Approvals page so the client can check it.';

comment on column public.messages.observation_source_url is 'Link backing up the observation.';

comment on column public.messages.pending_since is 'When this draft entered the approval queue. Set on insert, and reset whenever an edited or rejected draft is resubmitted as pending. Use this, not created_at, for the Pending Since column.';

comment on column public.notifications.recipient is 'Who this is for: "client" or "agency". Set by the sweep so the dispatcher does not have to guess, which is how the SMS fallback ended up always going to the agency.';

comment on table public.platform_settings is 'Single-row platform config for compliance footers. Set agency_postal_address and allow_agency_address_fallback to let clients without their own address still send.';

comment on column public.prospects.client_note is 'Free-text note the client keeps against this prospect. Written only through set_prospect_note, so the UI never needs update rights on the prospects table.';

comment on column public.prospects.unsubscribe_token is 'Opaque token for the one-click unsubscribe link. Random per prospect so the link cannot be guessed from an email address.';

comment on table public.raw_scrapes is 'Checkpoint of raw Apify scrape results, saved immediately after scraping and before filter/import. Lets a failed import be replayed without re-scraping.';

comment on column public.replies.intent is 'Only "interested" creates a hot lead and charges a credit. It needs a strong match to our outreach (thread or exact address) and explicit buying interest in what the client sells. existing_conversation means the reply belongs to correspondence outside our outreach.';

comment on column public.replies.match_method is 'How the reply was attached to a prospect: thread (replied inside our email thread), email (exact address we wrote to), or domain (company domain only, a weak match that must never create a hot lead on its own).';

comment on table public.scrape_jobs is 'One row per (campaign run, location). Lets WF0 fan out each location into its own short-lived execution and detect overall completion when the last location finishes.';

comment on column public.scrape_jobs.run_id is 'Groups all location jobs belonging to a single campaign trigger, so a re-trigger does not get confused with an earlier run.';

comment on table public.scrape_limits is 'Single-row config for campaign input caps and scrape watchdog timings. Clients are held to these; admins bypass them.';

comment on column public.scrape_limits.max_term_location_pairs is 'Cap on search_terms x locations. This product, not either count alone, is what drives Apify run time.';

